function navigationFoldIcon(collapse){return `<svg class="navigation-fold-icon" data-icon-library="ant-design-9402" data-icon="${collapse?'menu-fold':'menu-unfold'}" width="22" height="22" viewBox="0 0 1024 1024" fill="currentColor" aria-hidden="true"><path d="${NAVIGATION_FOLD_PATHS[collapse?'fold':'unfold']}"></path></svg>`;}
function updateWideModeControls(){const wide=document.body.classList.contains('sheet-wide'),button=$('#sidebar-toggle');if(button){button.setAttribute('aria-expanded',String(!wide));button.setAttribute('aria-label',wide?'展开左侧导航':'收起左侧导航');button.title=wide?'展开左侧导航':'收起左侧导航';button.innerHTML=navigationFoldIcon(!wide);}hideNavigationFlyout();}
let navigationFlyoutSource=null;
function hideNavigationFlyout(){const box=$('#navigation-flyout');if(box)box.hidden=true;navigationFlyoutSource=null;}
function showNavigationFlyout(source){
 if(!document.body.classList.contains('sheet-wide')||!matchMedia('(min-width:761px) and (hover:hover)').matches)return;
 if(navigationFlyoutSource===source)return;
 let box=$('#navigation-flyout');if(!box){box=document.createElement('div');box.id='navigation-flyout';box.hidden=true;document.body.append(box);}
 navigationFlyoutSource=source;const button=document.createElement('button');button.type='button';button.className='navigation-flyout-button';button.classList.toggle('active',source.classList.contains('active'));for(const [k,v] of Object.entries(source.dataset))button.dataset[k]=v;
 const icon=source.querySelector('svg')?.cloneNode(true);if(icon)button.append(icon);const text=document.createElement('span');text.textContent=source.getAttribute('aria-label')||source.textContent.trim();button.append(text);box.replaceChildren(button);box.hidden=false;
 const r=source.getBoundingClientRect();box.style.left=(r.right-2)+'px';box.style.top=Math.max(8,Math.min(r.top,innerHeight-box.offsetHeight-8))+'px';
}
document.addEventListener('click',event=>{if(event.target.closest('#sidebar-toggle')){document.body.classList.toggle('sheet-wide');updateWideModeControls();}else if(!event.target.closest('#navigation-flyout,.sidebar'))hideNavigationFlyout();});
document.addEventListener('mouseover',event=>{const source=event.target.closest('.sidebar .nav-item,.sidebar .workspace-shortcut');if(source)showNavigationFlyout(source);});
document.addEventListener('mouseout',event=>{if(!navigationFlyoutSource)return;const to=event.relatedTarget;if(to instanceof Node&&(navigationFlyoutSource.contains(to)||$('#navigation-flyout')?.contains(to)))return;if(event.target.closest('.sidebar .nav-item,.sidebar .workspace-shortcut,#navigation-flyout'))hideNavigationFlyout();});
document.addEventListener('focusin',event=>{const source=event.target.closest('.sidebar .nav-item,.sidebar .workspace-shortcut');if(source)showNavigationFlyout(source);});
document.addEventListener('focusout',event=>{const to=event.relatedTarget;if(to instanceof Node&&(navigationFlyoutSource?.contains(to)||$('#navigation-flyout')?.contains(to)))return;hideNavigationFlyout();});
document.addEventListener('scroll',hideNavigationFlyout,true);
window.addEventListener('resize',hideNavigationFlyout);
document.addEventListener('keydown',event=>{if(isTextComposing(event))return;if(event.key==='Escape')hideNavigationFlyout();});

