// One primary switcher per page, directly below the application header.
let pageSwitchObserver=null,pageSwitchResizeFrame=0,pageSwitchPending=null;
const PAGE_SWITCH_SHORT={attendanceView:{day:'当天考勤',month:'月考勤',history:'历史查询',schedule:'生产排班'},warehouseTab:{stock:'库存生产',processing:'转加工',allocation:'发货分配',returns:'退货隔离',closing:'日终结存',reconciliation:'盘发核对'},dispatchTab:{schedule:'排车安排',loads:'配送明细与实发确认',contractor:'承包方人员',fleet:'车辆司机'},settlementStage:{todo:'待处理',pending:'会计算票',rework:'重算',ready:'出纳复核',reviewed:'已复核'},returnStage:{register:'实物登记',account:'会计核定',review:'出纳复核',completed:'已完成'},salesView:{fulfillment:'发货',collection:'收款',regions:'地区',customers:'客户',products:'产品',markets:'市场',yields:'出品率',alerts:'催款'},crateView:{counts:'每日数量',events:'回筐流水',comparison:'发回核对','driver-requests':'司机确认',mapping:'筐型对应'}};
function pageSwitchKey(button){return JSON.stringify(Object.entries(button.dataset).sort(([a],[b])=>a.localeCompare(b)));}
function pageSwitchCurrent(bar){return bar.querySelector(':scope > button.active,:scope > button.primary,:scope > button[aria-selected="true"],:scope > button[aria-pressed="true"]');}
function setPageSection(bar,id){for(const link of bar.querySelectorAll(':scope > a')){const current=link.hash==='#'+id;link.classList.toggle('active',current);if(current)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current');}}
function observePageSections(){pageSwitchObserver?.disconnect();pageSwitchObserver=null;const bar=document.querySelector('#content > .owner-section-nav.page-switchbar');if(!bar)return;const sections=[...document.querySelectorAll('#content > .owner-section')];if(!sections.length)return;
 const top=parseFloat(getComputedStyle(bar).top)||0,line=top+bar.offsetHeight+22;
 let current=sections[0];for(const section of sections)if(section.getBoundingClientRect().top<=line)current=section;setPageSection(bar,current.id);
 if(typeof IntersectionObserver!=='function')return;
 // A narrow observation line follows the section under the switcher, without a
 // scroll handler that repeatedly measures tables, charts or every page node.
 pageSwitchObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting)setPageSection(bar,entry.target.id);},{rootMargin:`-${line}px 0px -${Math.max(0,window.innerHeight-line-1)}px 0px`,threshold:0});for(const section of sections)pageSwitchObserver.observe(section);
}
function setupPageSwitchbar(){pageSwitchObserver?.disconnect();const root=document.querySelector('#content');if(!root)return;let bar=root.querySelector(':scope > .owner-section-nav,:scope > .workflow-tabs,:scope > .factory-list-tabs');
 if(!bar&&page==='crates'){const source=root.querySelector('.workflow-tabs');if(source){bar=document.createElement('div');bar.className='workflow-tabs';bar.setAttribute('aria-label','筐子管理');for(const button of source.querySelectorAll(':scope > [data-crate-view]'))bar.append(button);source.className='crate-page-actions';source.closest('.resource-panel').before(bar);}}
 if(!bar){pageSwitchPending=null;return;}bar.classList.add('page-switchbar');const switchHead=root.querySelector(':scope > .page-head');if(switchHead&&(switchHead.compareDocumentPosition(bar)&Node.DOCUMENT_POSITION_PRECEDING))switchHead.after(bar);const controls=[...bar.querySelectorAll(':scope > button,:scope > a')];bar.style.setProperty('--switch-count',controls.length);
 if(!bar.hasAttribute('aria-label'))bar.setAttribute('aria-label','本页功能切换');
 for(const button of controls){if(button.tagName!=='BUTTON')continue;const full=button.textContent.trim();let short=full;for(const [key,labels] of Object.entries(PAGE_SWITCH_SHORT))if(button.dataset[key]&&labels[button.dataset[key]])short=labels[button.dataset[key]];
 if(short!==full){const desktop=document.createElement('span'),mobile=document.createElement('span');desktop.className='switch-label-full';mobile.className='switch-label-short';desktop.textContent=full;mobile.textContent=short;mobile.setAttribute('aria-hidden','true');button.replaceChildren(desktop,mobile);if(!button.hasAttribute('aria-label'))button.setAttribute('aria-label',full);}}
 if(pageSwitchPending?.page!==page)pageSwitchPending=null;const active=pageSwitchCurrent(bar);if(active&&pageSwitchPending?.key===pageSwitchKey(active)){const pending=pageSwitchPending;requestAnimationFrame(()=>{const current=document.querySelector('#content > .page-switchbar'),selected=current&&pageSwitchCurrent(current);if(pageSwitchPending===pending&&pending.page===page&&selected&&pageSwitchKey(selected)===pending.key){pageSwitchPending=null;current.scrollIntoView({block:'start',behavior:'instant'});}});}
 observePageSections();
}
if(typeof window!=='undefined'){
 window.addEventListener('click',e=>{const button=e.target.closest('.page-switchbar > button');if(button)pageSwitchPending={page,key:pageSwitchKey(button)};if(e.target.closest('[data-leave-choice="stay"]'))pageSwitchPending=null;},true);
 window.addEventListener('resize',()=>{if(pageSwitchResizeFrame)return;pageSwitchResizeFrame=requestAnimationFrame(()=>{pageSwitchResizeFrame=0;observePageSections();});},{passive:true});
}
document.addEventListener('click',e=>{const link=e.target.closest('.owner-section-nav.page-switchbar > a');if(!link)return;const section=document.getElementById(link.hash.slice(1));if(!section)return;e.preventDefault();setPageSection(link.parentElement,section.id);section.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});

async function refreshCurrentPage(){if(busy||navigationLoading)return;await requestPageTransition(async()=>{closeDialog();if(typeof finishedCache!=='undefined')finishedCache=null;if(typeof gelCache!=='undefined')gelCache=null;if(typeof fundsCache!=='undefined')fundsCache=null;render();notify('当前页面已刷新');});}
document.addEventListener('click',e=>{if(e.target.closest('#page-refresh-button'))refreshCurrentPage().catch(err);});
let pullRefreshStart=null,pullRefreshDistance=0;
function pullRefreshHint(){let e=document.getElementById('pull-refresh-hint');if(!e){e=document.createElement('div');e.id='pull-refresh-hint';e.setAttribute('role','status');e.hidden=true;document.body.append(e);}return e;}
document.addEventListener('touchstart',e=>{pullRefreshStart=null;pullRefreshDistance=0;if(innerWidth>760||scrollY>1||busy||navigationLoading||!data||!document.getElementById('overlay').hidden||document.body.classList.contains('mobile-nav-open')||e.touches.length!==1||e.target.closest('input,select,textarea,button,a,.table-wrap'))return;pullRefreshStart={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:true});
document.addEventListener('touchmove',e=>{if(!pullRefreshStart)return;const dx=e.touches[0].clientX-pullRefreshStart.x,dy=e.touches[0].clientY-pullRefreshStart.y;if(Math.abs(dx)>24||dy<0||scrollY>1){pullRefreshStart=null;pullRefreshHint().hidden=true;return;}pullRefreshDistance=Math.min(dy,140);if(dy>16){if(e.cancelable)e.preventDefault();const hint=pullRefreshHint();hint.hidden=false;hint.textContent=dy>=80?'松开刷新':'下拉刷新';}},{passive:false,capture:true});
document.addEventListener('touchend',()=>{const ready=!!pullRefreshStart&&pullRefreshDistance>=80;pullRefreshStart=null;pullRefreshDistance=0;const hint=pullRefreshHint();hint.hidden=true;if(ready)refreshCurrentPage().catch(err);},{passive:true});
document.addEventListener('touchcancel',()=>{pullRefreshStart=null;pullRefreshDistance=0;pullRefreshHint().hidden=true;},{passive:true});
